use conc_case::parallel_map;
use std::time::{Duration, Instant};

#[test]
fn preserves_input_order() {
    let items: Vec<i32> = (0..100).collect();
    let out = parallel_map(items, 4, |x| x * 3);
    let want: Vec<i32> = (0..100).map(|x| x * 3).collect();
    assert_eq!(out, want, "results must be in INPUT order");
}

#[test]
fn actually_runs_in_parallel() {
    // 8 sleepy items on 4 workers: parallel ~200ms, serial ~800ms.
    let items: Vec<u64> = (0..8).collect();
    let start = Instant::now();
    let out = parallel_map(items, 4, |x| {
        std::thread::sleep(Duration::from_millis(100));
        x + 1
    });
    let elapsed = start.elapsed();
    assert_eq!(out, vec![1, 2, 3, 4, 5, 6, 7, 8]);
    assert!(
        elapsed.as_millis() < 500,
        "8x100ms items on 4 workers took {:?} - not actually parallel",
        elapsed
    );
}

#[test]
fn edge_cases() {
    assert_eq!(parallel_map(Vec::<i32>::new(), 4, |x| *x), Vec::<i32>::new());
    assert_eq!(parallel_map(vec![7], 16, |x| x * 2), vec![14]);
}

