use std::thread;

pub fn parallel_map<T, U, F>(items: Vec<T>, workers: usize, f: F) -> Vec<U>
where
    T: Send + Sync,
    U: Send,
    F: Fn(&T) -> U + Sync,
{
    if items.is_empty() {
        return Vec::new();
    }
    let workers = workers.max(1).min(items.len());
    let chunk = (items.len() + workers - 1) / workers;
    let mut out: Vec<Option<U>> = Vec::new();
    out.resize_with(items.len(), || None);

    thread::scope(|scope| {
        for (input, output) in items.chunks(chunk).zip(out.chunks_mut(chunk)) {
            let f = &f;
            scope.spawn(move || {
                for (i, item) in input.iter().enumerate() {
                    output[i] = Some(f(item));
                }
            });
        }
    });

    out.into_iter().map(|v| v.unwrap()).collect()
}

