use std::sync::Mutex;
use std::thread;

pub fn parallel_map<T, U, F>(items: Vec<T>, workers: usize, f: F) -> Vec<U>
where
    T: Send + Sync,
    U: Send,
    F: Fn(&T) -> U + Sync,
{
    if items.is_empty() {
        return Vec::new();
    }
    let workers = workers.max(1).min(items.len());
    let chunk = (items.len() + workers - 1) / workers;
    let collected: Mutex<Vec<(usize, Vec<U>)>> = Mutex::new(Vec::new());

    thread::scope(|scope| {
        for (w, input) in items.chunks(chunk).enumerate() {
            let f = &f;
            let collected = &collected;
            scope.spawn(move || {
                let mapped: Vec<U> = input.iter().map(f).collect();
                collected.lock().unwrap().push((w, mapped));
            });
        }
    });

    // chunks reassembled newest-first instead of by input position
    let mut chunks = collected.into_inner().unwrap();
    chunks.sort_by(|a, b| b.0.cmp(&a.0));
    chunks.into_iter().flat_map(|(_, v)| v).collect()
}
